// src/shared/net.ts
var MAP_ENVIRONMENT_TO_BASE_URL = {
  dev: "https://fib-dev.fib.iq",
  stage: "https://fib-stage.fib.iq",
  prod: "https://fib.prod.fib.iq"
};
var BaseHTTP = class {
  #baseUrl;
  #clientId;
  #clientSecret;
  #grantType = "client_credentials";
  constructor(clientId, clientSecret, env) {
    const rawBaseURL = MAP_ENVIRONMENT_TO_BASE_URL[env];
    if (!rawBaseURL) {
      throw new Error(`Invalid environment: ${env}`);
    }
    this.#clientId = clientId;
    this.#clientSecret = clientSecret;
    this.#baseUrl = new URL(rawBaseURL);
  }
  getBaseUrl() {
    return this.#baseUrl;
  }
  getHeaders(accessToken, omitContentType = false) {
    const headers = new Headers();
    if (!omitContentType) headers.set("Content-Type", "application/json");
    headers.set("X-Application-Type", "3rd-party");
    headers.set("X-Application-Platform", "node");
    headers.set("Authorization", `Bearer ${accessToken}`);
    return headers;
  }
  async authenticate(signal) {
    const url = new URL(
      "/auth/realms/fib-online-shop/protocol/openid-connect/token",
      this.#baseUrl
    );
    const body = new URLSearchParams();
    body.set("grant_type", this.#grantType);
    body.set("client_id", this.#clientId);
    body.set("client_secret", this.#clientSecret);
    return fetch(url.href, {
      body,
      signal,
      method: "POST"
    });
  }
};

// src/payout/net.ts
var HTTP = class extends BaseHTTP {
  constructor(clientId, clientSecret, env) {
    super(clientId, clientSecret, env);
    throw new Error("Payout SDK is not implemented yet");
  }
  static getClient(clientId, clientSecret, env) {
    return new this(clientId, clientSecret, env);
  }
};

// src/payout/index.ts
var PayoutSDK = class {
  #http;
  #environment;
  constructor(clientId, clientSecret, environment) {
    this.#environment = environment;
    this.#http = HTTP.getClient(clientId, clientSecret, this.#environment);
  }
  authenticate(signal) {
    return this.#http.authenticate(signal);
  }
  static getClient = (clientId, clientSecret, environment) => {
    return new this(clientId, clientSecret, environment);
  };
};
export {
  PayoutSDK
};
